import base64

configmap = {"DATABASE_HOST": "db.internal", "FEATURE_FLAGS": "checkout_v2"}
secret_b64 = {"DATABASE_PASSWORD": base64.b64encode(b"s3cr3t-value").decode()}


def build_env(configmap, secret_b64):
    env = dict(configmap)
    for key, encoded in secret_b64.items():
        env[key] = base64.b64decode(encoded).decode()
    return env


def mask(env, secret_keys):
    return {k: ("***" if k in secret_keys else v) for k, v in env.items()}


env = build_env(configmap, secret_b64)
for key, value in sorted(mask(env, secret_b64.keys()).items()):
    print(f"{key}={value}")
